Let $\mathtt{b}_0\in \mathbb{N}$ be fixed. For each $\vec{\mathtt{b}}\in \mathbb{N}^\nu$ such that $|\vec{\mathtt{b}}|\le s_0+\mathtt{b}_0$, assume that  $\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})$ and $ [\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A}),\partial_x]$ are Lip-$0$-tame operators up to $\mathtt{S}$ with tame constants $\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s),\mathfrak{M}^\gamma_{[\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A}),\partial_x]}(0,s)$ for $s\in [s_0,\mathtt{S}]$. Then, for all $\vec{b}\in \mathbb{N}^\nu$  such that $|\vec{b}|\le \mathtt{b}_0$, $\partial_{\varphi}^{\vec{b}}(\mathcal{A})$ is  Lipschitz-0-modulo tame up to $\mathtt{S}$ and
\begin{align}\label{moduks222sdsdd2sd}
\mathfrak{M}^{\sharp,\gamma}_{\partial_{\varphi}^{\vec{b}}(\mathcal{A})}(0,s)\le_{s_0,\mathtt{b}_0} \sum_{\substack{\vec{\mathtt{b}}\in \mathbb{N}^\nu, \\ |\vec{\mathtt{b}}|\le s_0+\mathtt{b}_0}}\left( \mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s) + \mathfrak{M}^\gamma_{[\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A}),\partial_x]}(0,s)\right).
\end{align}

To simplify the notation, let us denote for fixed $\omega,\omega_1,\omega_2\in \Omega$, 
\begin{align}\label{reminiscings1}
\Delta_{12}^{k}\mathcal{A}:=\begin{cases}
\mathcal{A}(\omega), & \text{ if  $k=0$,}\\
\gamma \frac{\mathcal{A}(\omega_1)-\mathcal{A}(\omega_2)}{|\omega_1-\omega_2|}, & \text{ if $k=1$.}
\end{cases}
\end{align}

First, we test the operator $\mathcal{A}$ with a monomial $ h(\varphi,x):=e^{\text{i} (l' \cdot \varphi + j' x)}$, then it follows from the definition of $\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s)$ that
\begin{align*}
\rVert \Delta_{12}^{k}\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})h\rVert_s^2 &\le C\left(\left(\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s)  \right)^2\rVert h\rVert_{s_0}^2 + \left(\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s_0)  \right)^2\rVert h\rVert_{s}^2\right)\\
& = C\left(\left(\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s)  \right)^2 \langle l', j'\rangle^{2s_0}  + \left(\mathfrak{M}^\gamma_{\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s_0)  \right)^2\langle l', j' \rangle^{2s}\right),
\end{align*}
Using the matrix representation of a linear  operator in \eqref{matrix_rep_2},  we have
\[
\left(\Delta_{12}^k\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})\right)^{j'}_j(l-l')=\text{i}^{|\vec{\mathtt{b}}|}(l-l')^{\vec{\mathtt{b}}}(\Delta_{12}^k\mathcal{A})^{j'}_j(l-l').
\]
Therefore,  the above inequality for $\rVert \Delta_{12}^{k}\partial_{\varphi}^{\vec{\mathtt{b}}}(\mathcal{A})h\rVert_s^2 $ gives us
\begin{align}\label{fixsdsd2sd}
\sum_{(l,j)\in \mathbb{Z}^{\nu+1}}\langle l,j\rangle^{2s}|(l-l')^{\vec{\mathtt{b}}}|^2 \left|\left( \Delta_{12}^{k}\mathcal{A}\right)^{j'}_{j}(l-l')\right|^2 \le C\left(\left(\mathfrak{M}^\gamma_{\partial_\varphi^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s)  \right)^2 \langle l', j'\rangle^{2s_0}  + \left(\mathfrak{M}^\gamma_{\partial_\varphi^{\vec{\mathtt{b}}}(\mathcal{A})}(0,s_0)  \right)^2\langle l', j' \rangle^{2s}\right).
\end{align}
Similarly, using the matrix representation, 
\[
([\Delta_{12}^k\partial_\varphi^{\vec{\mathtt{b}}}(\mathcal{A}),\partial_x])^{j'}_j(l-l') = \text{i}^{|\vec{\mathtt{b}}| + 1}(l-l')^{\vec{\mathtt{b}}}(j-j')(\Delta_{12}^k\mathcal{A})^{j'}_j(l-l'),
\]
