\begin{align}
\sum_{(l,j)\in \mathbb{Z}^{\nu+1}}&\langle l,j\rangle^{2s}|(l-l')^{\vec{\mathtt{b}}}|^2|j-j'|^2 \left|\left( \Delta_{12}^{k}\mathcal{A}\right)^{j'}_{j}(l-l')\right|^2\nonumber\\
