\end{align}
Since $\xi\mapsto m_{1,\alpha}$ is monotone increasing for $\xi\ge 0$ (\ref{extension_ofoperators2} of Proposition~\ref{nichts2}), we see from \eqref{lambdadeffsd} that 
\[
\lim_{\xi \to \infty}\left|\frac{\int_{0}^1\partial_\xi\lambda_\alpha(\xi + (t-1)k)dt}{\langle \xi \rangle^{\alpha-1}}\right| =\lim_{\xi \to \infty}  \frac{\int_{0}^1|\partial_\xi\lambda_\alpha(\xi + (t-1)k)|dt}{\langle \xi \rangle^{\alpha-1}} \ge_\alpha 1,
\]
