&=\left| \partial_\xi^{\eta}\left(|\kappa_{k,1-\alpha}(\xi)|^2 \int_0^1\partial_\xi^{2}\lambda_{\alpha}(\xi + (t-1)k)dt\right)\right|\\
& = \left|\sum_{\eta_1+\eta_2=\eta}C_{\eta_1,\eta_2}  \partial_\xi^{\eta_1}(\kappa_{k,1-\alpha}(\xi)^2)\int_0^{1}\partial_\xi^{\eta_2+2}\lambda_{\alpha}(\xi + (t-1)k)dt\right|.
\end{align*}
