We split the proof into three steps. In the first step, we rewrite the Hamiltonian $\mathcal{H}$ in terms of $f$. In the second step, we specify the linear, quadratic and cubic terms of $\nabla\mathcal{H}(f)$. Afterwards, we integrate them to recover the quadratic, cubic and quartic terms of $\mathcal{H}$. In the last step, we show that the terms in $\nabla \mathcal{H}$ that are homogeneous of degree at least $4$ in $f$ are of the form in \eqref{gradh5}. 

\textbf{Expression for $\nabla\mathcal{H}$ in terms of $f$.}
 We first rewrite the Hamiltonian $\mathcal{H}$ more explicitly. Given $f\in L^2_0$, we set 
 \begin{align}\label{rtof}
 R(\theta):=\sqrt{1+f(\theta)}, \quad \text{ and }z(\theta):=R(\theta)(\cos \theta, \sin \theta),
\end{align}
so that $z(\theta)$ represents a parametrization of $\partial D$, determined by $f$. Using the identity:
\[
\int_{D}\frac{1}{|x-y|^{\alpha}}dy = -\frac{1}{2-\alpha}\int_{\partial_D}\frac{(x-y)}{|x-y|^{\alpha}}\cdot \vec{n}(y)d\sigma = \frac{1}{2-\alpha}\int_{\mathbb{T}}\frac{(x-z(\eta))\cdot \partial_{\eta}z(\eta)^{\perp}}{|x-z(\eta)|^{\alpha}}d\eta,
\]
which simply follows from  integration by parts, we find that the corresponding stream function $\Psi(z(\theta))$ in \eqref{stream_function} can be written as
\begin{align}\label{stream_2}
\Psi(z(\theta)) = \frac{1}{2-\alpha}\int_{\mathbb{T}} (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}\left(R(\theta)R(\eta) + \frac{(R(\theta)-R(\eta))^2}{2-2\cos(\theta-\eta)}\right)^{-\frac{\alpha}{2}}(A_1+A_2+A_3)d\eta,
\end{align}
where 
\[
A_1:=R(\theta)R'(\eta)\sin(\theta-\eta), \quad A_2 = R(\eta)R(\theta)(1-\cos(\theta-\eta)), \quad A_3=-R(\eta)(R(\theta)-R(\eta)).
\]
Recalling \eqref{l20gradient} and replacing $R(\theta)$ in \eqref{stream_2} by $\sqrt{1+f(\theta)}$, we obtain that 
\begin{equation}\label{grad_hamiltonian1}
\begin{aligned}
\nabla\mathcal{H}(f) = \Psi(z(\theta))  &=\frac{1}{2-\alpha} \int(2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}G_1(f(\theta),f(\eta),{J})f'(\eta)\sin(\theta-\eta)d\eta\\
& \ +\frac{1}{2(2-\alpha)} \int(2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}G_2(f(\theta),f(\eta),{J})d\eta \\
& \ - \frac{1}{2-\alpha}\int(2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}G_3(f(\theta),f(\eta),{J})(f(\theta)-f(\eta))d\eta,
\end{aligned}
\end{equation}
where
\begin{equation}\label{grad_hamiltonian2}
\begin{aligned}
&{J}=J(\theta,\eta):=\frac{(f(\theta)-f(\eta))^2}{2-2\cos(\theta-\eta)},\\
&G_1(x,y,z) = \left(\sqrt{1+x}\sqrt{1+y}+z\frac{\left(\sqrt{1+x}-\sqrt{1+y}\right)^2}{(x-y)^2}\right)^{-\frac{\alpha}{2}}\frac{\sqrt{1+x}}{2\sqrt{1+y}}\\
&G_2(x,y,z) = \left(\sqrt{1+x}\sqrt{1+y}+z\frac{\left(\sqrt{1+x}-\sqrt{1+y}\right)^2}{(x-y)^2}\right)^{-\frac{\alpha}{2}}\sqrt{1+x}\sqrt{1+y}\\
&G_3(x,y,z) = \left( \sqrt{1+x}\sqrt{1+y}+z\frac{\left(\sqrt{1+x}-\sqrt{1+y}\right)^2}{(x-y)^2} \right)^{-\frac{\alpha}{2}}\left( \frac{\sqrt{1+y}(\sqrt{1+x}-\sqrt{1+y})}{x-y}\right).
\end{aligned}
\end{equation}

\textbf{Explicit formulae for $\nabla\mathcal{H}_2$, $\nabla\mathcal{H}_3$ and $\nabla\mathcal{H}_4$.} We note that the functions $G_1,G_2,G_3$ are analytic near the origin in $\mathbb{R}^3$ (more precisely, they can be extended so that they are analytic near the origin). In order to find $\mathcal{H}_2,\mathcal{H}_3,\mathcal{H}_4$, which will correspond to the quadratic, cubic and quartic parts of the Hamiltonian $\mathcal{H}$,  we will compute the Taylor series coefficients of $G_i$ near the origin. For $\mathcal{H}_2$, we find that
\[
G_1(0,0,0) = \frac{1}{2},\quad \partial_xG_2(0,0,0)=\partial_yG_2(0,0,0)=\frac{2-\alpha}{4},\quad G_3(0,0,0) = \frac{1}{2}.
\]
This gives the linear term of $\nabla\mathcal{H}$, that is, from \eqref{grad_hamiltonian1}, it follows that
\[
\nabla\mathcal{H}_2(f) = -\frac{1}{2}\Lambda^{\alpha-1}f(\theta) + \frac{1}{4}T_\alpha f(\theta).
\]
Integrating this with respect to $f$, we find that
\begin{align}\label{H2}
\mathcal{H}_2 = -\frac{1}{4}\int_{\mathbb{T}}f\Lambda^{\alpha-1}fd\theta + \frac{T_\alpha}{8}f^2d\theta.
\end{align}
Similarly, we compute $\nabla\mathcal{H}_3,\nabla\mathcal{H}_4$ and find that
\begin{align*}
\nabla\mathcal{H}_3(f) & = \frac{\alpha}{16}\int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}(3f(\theta)^2 - 2f(\theta)f(\eta)-f(\eta)^2)d\eta  - \frac{\alpha}{16}\int (2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}d\eta f(\theta)^2.
\end{align*}
and
\begin{align*}
\nabla \mathcal{H}_4(f)&  = -\frac{\alpha}{192}\int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}((7\alpha+16)f(\theta)^3 - 3(\alpha+4)f(\theta)^2f(\eta)-3\alpha f(\theta)f(\eta)^2 - (\alpha+4)f(\eta)^3)d\eta \nonumber\\
& \ + \frac{\alpha}{48}\int (2-2\cos(\theta-\eta))^{-1-\frac{\alpha}{2}} (f(\theta)-f(\eta))^3 d\eta + \frac{\alpha}{96}(2+\alpha)T_\alpha f(\theta)^3.
\end{align*}
Integrating them with respect to $f$, one can find that
\begin{align*}
&\mathcal{H}_3(f) =  \frac{\alpha}{16}\int f^2 \Lambda^{\alpha-1}fd\theta   -\frac{\alpha}{48}T_\alpha\int f^3d\theta \\
&\mathcal{H}_4(f) = -\frac{\alpha(\alpha+4)}{192}\int f^3\Lambda^{\alpha-1}fd\theta -\frac{\alpha^2}{256}\int f^2 \Lambda^{\alpha-1}(f^2)d\theta + \frac{\alpha}{384}\int M_{4}(f)d\theta + \frac{\alpha}{384}(2+\alpha)T_\alpha \int f(\theta)^4 d\theta,
\end{align*}
where $T_\alpha$ and  $M_4$ are as in \eqref{def_talpha}. With \eqref{H2}, we obtain \eqref{expansion_2}.

\textbf{Expression for $\mathcal{H}_5$.}
Let $\nabla\mathcal{H}_5:=\nabla\mathcal{H}-\sum_{i=2}^4\nabla\mathcal{H}_i$. Since all linear, quadratic and cubic contributions of $f$ on $\nabla\mathcal{H}$ are contained in $\sum_{i=2}^4\nabla\mathcal{H}_i$, we see from \eqref{grad_hamiltonian1} that
\begin{equation}\label{H_52}
\begin{aligned}
\nabla \mathcal{H}_5(f)  & =\frac{1}{2-\alpha} \int(2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}G_{1,\ge 3}(f(\theta),f(\eta),{J})f'(\eta)\sin(\theta-\eta)d\eta\\
& \ +\frac{1}{2(2-\alpha)} \int(2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}G_{2,\ge 4}(f(\theta),f(\eta),{J})d\eta \\
& \ - \frac{1}{2-\alpha}\int(2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}G_{3,\ge 3}(f(\theta),f(\eta),{J})(f(\theta)-f(\eta))d\eta,
\end{aligned}
\end{equation}
where $G_{1,\ge3}$ and $G_{2,\ge3}$ collect all the terms from $G_1$ and $G_2$ that are homogeneous of degree at least $3$ and $G_{2\ge 4}$ collects the terms from $G_2$ that are homogeneous of degree at least $4$. We claim that there exist $F_{1,\ge3}(x,y,z),F_{2,\ge4}(x,y,z)$, which are analytic near $(0,0,0)$, homogeneous of degree at least $3$ and $4$ respectively, and
\begin{align}\label{H_53}
\nabla \mathcal{H}_5(f) &= \int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}F_{1,\ge3}(f(\theta),f(\eta),{J})(f(\theta)-f(\eta))d\eta\nonumber \\
& \ +\int (2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}F_{2,\ge4}(f(\theta),f(\eta),{J})d\eta.
\end{align}
Clearly, the second and the third integrals in \eqref{H_52} are already of the form in \eqref{H_53}, thus once we prove that the first integral in \eqref{H_52} is of the form \eqref{H_53}, we will finish the proof of the proposition.

 For the first integral in \eqref{H_52}, let us write the integral, using the Taylor expansion of $G_{1,\ge3}$, as 
\begin{align}
I_1:=\int&(2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}G_{1,\ge 3}(f(\theta),f(\eta),{J})f'(\eta)\sin(\theta-\eta)d\eta\nonumber\\
&  = \sum_{n=4}^{\infty}\sum_{k+l+2m=n}C_{k,l,m}f(\theta)^{k}\underbrace{\int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}f(\eta)^lf'(\eta){J}^{m}\sin(\theta-\eta)d\eta}_{=:a_{l,m}}.\label{I_def}
\end{align}
 Using integration by parts, it follows immediately that
\begin{align}
&a_{l,m} = f(\theta)d_{l,m}a_{l-1,m} + c_{l,m},\label{a_sequence}\\
&a_{0,m} = \frac{2-\alpha-2m}{4(2m+1)}\int (2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}(f(\theta)-f(\eta)){J}^m d\eta,\nonumber\\
 &\quad \quad + \frac{2m+\alpha-1}{2m+1}\int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}(f(\theta)-f(\eta)){J}^m d\eta, \label{a_sequence_0}
\end{align}
where
