& = \frac{1}{n!}\sum_{i=0}^{n}A_n(u) +\frac{1}{n!}\int_0^1 A_{n+1}(\Phi_t(u))(1-t)^ndt,\\
&A_{0}:=H,\quad A_{n+1} :=\left\{ A_n,F\right\}, \text{ for $n\ge 0$.}
\end{aligned}
\end{equation}

Since $F$ is supported on a finite dimensional space $E$, the map $\Phi^t$ is well-defined for all $t>0$ which depends on $t$ smoothly. That $\Phi_t$ is symplectic transformation is a classical result  (see \cite{hubbard2004proof} for example). To see the expansion in \eqref{expansion2s3dsss}, let $f(t):=H(\Phi_t(u))$. From \eqref{poisson_bracket} and the fact that $\Phi_t$ is the flow map of the Hamiltonian $F$, it follows that
\begin{align*}
&f^{(n+1)}(t)=\left\{ A^n,F\right\}(\Phi_t(u)).
\end{align*}
Therefore \eqref{expansion2s3dsss} follows from \eqref{elementary_taylor}.

