& \ + \sum_{\substack{j_1+j_2+j_3 = 0 \\ (j_1,j_2,j_3 ) \in \mathcal{A}_3^c}} \left( H_{3,j_1,j_2,j_3}- \frac{\text{i}}{\pi} \left(j_1\kappa_{j_1} +j_2\kappa_{j_2} +j_3\kappa_{j_3}  \right)F^{(3)}_{j_1,j_2,j_3}\right)f_{j_1}f_{j_2} f_{j_3},\label{sssperp2}
\end{align}
where 
\begin{align}\label{defi_1sd3a}
\mathcal{A}_3 := \left\{ (j_1,j_2,j_3)\in  \mathcal {\mathbb{Z}}^3:\ \text{at least two of $\left\{j_1,j_2,j_3 \right\}$ are in $S$}\right\}.
\end{align}  We claim that
\begin{align}\label{sssclaim}
j_1\kappa_{j_1} +j_2\kappa_{j_2} +j_3\kappa_{j_3}  \ne 0, \quad \text{if $j_1+j_2+j_3 = 0$.}
\end{align}
To see this, let us suppose to the contrary that there exist $j_1,j_2,j_3$ such that
\[
j_1+j_2+j_3=0, \quad j_1\kappa_{j_1} +j_2\kappa_{j_2} +j_3\kappa_{j_3}  = 0, \quad j_1,j_2,j_3\ne 0.
\]
Without loss of generality, we assume that $j_1>0$, $j_2>0$, hence $|j_3|>|j_1|,|j_2|$. From $\kappa_j$ in \eqref{moreexplicits2} and $j_1+j_2+j_3=0$, it holds that
\[
j_1\kappa_{j_1} +j_2\kappa_{j_2} +j_3\kappa_{j_3} = 0 \implies j_1m^\circ_{1,\alpha}(j_1)+j_2m^\circ_{1,\alpha}(j_2)+j_3m^\circ_{1,\alpha}(j_3) = 0.
\]
Therefore, we have $j_1\left( m^\circ_{1,\alpha}(j_1)-m^\circ_{1,\alpha}(j_3) \right) + j_2\left( m^\circ_{1,\alpha}(j_2)-m^\circ_{1,\alpha}(j_3) \right) = 0$. Thanks to \ref{extension_ofoperators2} of Proposition~\ref{nichts2}, we have that 
\begin{align}\label{evensdsysd}
j\mapsto m^\circ_{1,\alpha}(j)\text{ is monotone increasing and even,}
\end{align} which yields a contradiction. This proves the claim~\eqref{sssclaim}. Therefore,  we can define $F^{(3)}$ to be 
\begin{align}\label{def_F3}
F^{(3)}_{j_1,j_2,j_3} = 
\begin{cases}
\frac{2\pi H_{3,j_1,j_2,j_3}}{2\text{i} \left(j_1\kappa_{j_1} +j_2\kappa_{j_2} +j_3\kappa_{j_3} \right)}  & \text{ if $(j_1,j_2,j_3) \in \mathcal{A}_3$},\\
0 & \text{ otherwise.}
\end{cases}
\end{align}
From \eqref{H33expansion}, \eqref{sssperp2} and \eqref{def_F3}, we obtain \eqref{m_H3}. Indeed,  the modified Hamiltonian does not change the terms involving more than $2$ components in the normal site, that is 
\begin{align}\label{sd11sdsdx2x}
H^{(3)}_3(f) = \mathcal{H}_{3,2}+\mathcal{H}_{3,3},
\end{align}
which gives \eqref{m_H3}.

\textbf{Proof of (2).} From \eqref{m_H3}, and $\mathcal{H}^{(3)}_3$ in \eqref{H33expansion}, we have
\begin{align}\label{h2andf3}
\left\{ \mathcal{H}_2, F^{(3)}\right\} = -\mathcal{H}_{3,\le 1}:=-(\mathcal{H}_{3,0} + \mathcal{H}_{3,1}),
\end{align}
and 
\begin{align}\label{H_34}
{H}^{(3)}_4 = \mathcal{H}_4 + \frac{1}{2}\left\{ \mathcal{H}_{3,\le 1},F^{(3)}\right\} + \left\{ {H}^{(3)}_3,F^{(3)}\right\}.
\end{align}
To compute the Poisson bracket, we write $F^{(3)}$ as
\begin{align}\label{def_F3333333}
F^{(3)}(f) = 3\sum_{\substack{j_1+j_2+j_3 = 0 \\ j_1,j_2\in S\\ j_3\in S^\perp}}F^{(3)}_{j_1,j_2,j_3}f_{j_1}f_{j_2}f_{j_3},
\end{align}
which follows from \eqref{def_F3} and that there is no $j_1,j_2,j_3\in S$ such that $j_1+j_2+j_3 =0$ (see \ref{tangent_2}).  Therefore, we have that for $h\in L^2(\mathbb{T})$, 
\begin{align}\label{rlsd1sdfff}
\left( \nabla F^{(3)}(f), h \right)_{L^2} &= 2\pi \cdot 6\sum_{j_1 \in S}\left(\sum_{\substack{j_2+j_3 = j_1 \\ j_2\in S, \\ j_3\in S^\perp}}F^{(3)}_{-j_1,j_2,j_3}f_{j_2}f_{j_3} \right)\overline{h}_{j_1} + 2\pi \cdot 3\sum_{j_3 \in S^\perp}\left(\sum_{\substack{j_1+j_2 = j_3 \\j_1, j_2\in S}}F^{(3)}_{j_1,j_2,-j_3}f_{j_1}f_{j_2} \right)\overline{h}_{j_3}\nonumber\\
& =:  6\int  \Pi_{S}K_1(v,z)h dx + 3\int \Pi_{S^\perp}K_2(v,v)hdx,
\end{align}
where 
\begin{align}\label{K12def}
K_1(v,z) =\sum_{j_2+j_3 = j}F^{(3)}_{-j,j_2,j_3}v_{j_2}z_{j_3}e^{\text{i} j x}, \quad \text{ and }\quad K_2(v,v) =\sum_{j_1+j_2 = j}F^{(3)}_{j_1,j_2,-j}v_{j_1}v_{j_2}e^{\text{i} j x}.
\end{align}
From \eqref{K12def}, one can easily see that
\begin{align}\label{K1K2relation}
\int v\Pi_{S}K_1(w,z)dx = \int z\Pi_{S^\perp}K_2(w,v)dx, \quad \text{ for $v,w\in H_S$ and $z\in H_{S^\perp}$}.
\end{align}
Hence \eqref{rlsd1sdfff}  tells us that \begin{align}\label{gradf2s2s}
\nabla F^{(3)}(f) = 6\Pi_SK_1(v,z) + 3\Pi_{S^\perp}K_2(v,v).
\end{align}
Furthermore, from $\mathcal{H}_3$ and $\mathcal{H}_{3,\le 1}$ in \eqref{expansion_2} and \eqref{h2andf3}, we see that 
\begin{align}\label{131hsd1}
\nabla \mathcal{H}_{3,\le 1}(f) & =  \frac{\alpha}{16}\Pi_S\left(2v\Lambda^{\alpha-1} v + \Lambda^{\alpha-1}(v^2) + 2v\Lambda^{\alpha-1}z + 2z\Lambda^{\alpha-1} v + 2\Lambda^{\alpha-1}(vz) \right) - \frac{\alpha}{16}T_\alpha\Pi_S \left(v^2+2vz \right)\nonumber\\
& +\frac{\alpha}{16}\Pi_{S^\perp}\left(\Lambda^{\alpha-1}(v^2) + 2v\Lambda^{\alpha-1} v \right)  -\frac{\alpha}{16}T_\alpha\Pi_{S^\perp}(v^2).
\end{align}
and from \eqref{m_H3}, we have
\begin{align}\label{h2msd1x}
\nabla {H}^{(3)}_3(f) &= \frac{\alpha}{16}\Pi_S\left(2z\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2) \right) - \frac{\alpha}{16}T_\alpha \Pi_S z^2 \nonumber\\
& \ + \frac{\alpha}{16}\Pi_{S^\perp}\left( 2v\Lambda^{\alpha-1}z + 2\Lambda^{\alpha-1}(vz) + 2z \Lambda^{\alpha-1}v + 2z \Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2)\right) - \frac{\alpha}{16}T_\alpha \Pi_{S^\perp}\left( 2vz + z^2\right).
\end{align}
Using \eqref{gradf2s2s}, \eqref{131hsd1} and the definition of the Poisson bracket in \eqref{poisson_bracket}, we have
\begin{align}\label{eq10}
\left\{ \mathcal{H}_{3,\le 1} , F^{(3)}\right\} & = \frac{3\alpha}{16}\int \left( \Lambda^{\alpha-1}(v^2) + 2v \Lambda^{\alpha-1} v - T_\alpha v^2 \right)\partial_x\Pi_{S^\perp}K_2(v,v)dx\nonumber \\
& \ +\underbrace{ \frac{3\alpha}{8}\int \left(2v\Lambda^{\alpha-1} v + \Lambda^{\alpha-1}(v^2) - T_\alpha v^2\right)\partial_x \Pi_SK_1(v,z) dx}_{=0 \text{ thanks to \ref{tangent_2}}} \nonumber\\
& \ + \frac{3\alpha}{4}\int \left(v\Lambda^{\alpha-1}z + z\Lambda^{\alpha-1} v + \Lambda^{\alpha-1}(vz) - T_\alpha vz \right)\partial_x \Pi_{S}K_1(v,z)dx.
\end{align}
Similarly, using \eqref{h2msd1x} and \eqref{gradf2s2s}, we have
\begin{align}\label{eq11}
\left\{ {H}^{(3)}_3,F^{(3)}\right\} & =  \frac{3\alpha}{8}\int \left( v\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(vz) + z\Lambda^{\alpha-1}v - T_\alpha vz \right)\partial_x \Pi_{S^\perp}K_2(v,v)dx \nonumber\\
& \ + \frac{3\alpha}{16} \int \left( 2z\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2) - T_\alpha z^2\right)\partial_x \Pi_{S^\perp}K_2(v,v)dx\\
& \ +\frac{3\alpha}{8}\int \left(2z\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2) - T_\alpha z^2 \right)\partial_x \Pi_S K_1(v,z)dx \nonumber
\end{align}
Collecting the terms involving only tangential sites or  two normal sites, we find that
\begin{align*}
\frac{1}{2}&\left\{ \mathcal{H}_{3,\le 1},F^{(3)}\right\} + \left\{ {H}^{(3)}_3,F^{(3)}\right\}\\
& = \frac{3\alpha}{32}\int \left( \Lambda^{\alpha-1}(v^2) + 2v \Lambda^{\alpha-1} v - T_\alpha v^2 \right)\partial_x\Pi_{S^\perp}K_2(v,v)dx\\
& \ + \frac{3\alpha}{8}\int \left(v\Lambda^{\alpha-1}z + z\Lambda^{\alpha-1} v + \Lambda^{\alpha-1}(vz) - T_\alpha vz \right)\partial_x \Pi_{S}K_1(v,z)dx \\
& \ + \frac{3\alpha}{16} \int \left( 2z\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2) - T_\alpha z^2\right)\partial_x \Pi_{S^\perp}K_2(v,v)dx\\
& \ + R(v^3z) + R(vz^3)+R(z^4),
\end{align*}
for some multilinear map $R$. With \eqref{H_34}, this proves \eqref{quartic_11122}. Also, Lemma~\ref{momentum1} implies that $H^{(3)}_5$ satisfies \eqref{conserve_momentum}. 

\textbf{Proof of (3).} $\mathcal{A}_3$ is a finite set since it is contained in $[-2K,2K]^3$, where $K = \max_{i=1,\ldots \nu, \quad j_i \in S} |j_{i}|$


