\rVert q \rVert^{\text{Lip}(\gamma,\Omega_1)}_{s} \le_{\mathtt{pe},s} \varepsilon^{3} + \varepsilon\rVert \mathfrak{I}_{\delta}\rVert^{\text{Lip}(\gamma,\Omega_1)}_{s+\mu_0}, \quad \rVert d_i q(i_0)[\hat{\textbf{\i}}] \rVert_s \le_{\mathtt{pe},s} \varepsilon\left( \rVert \hat{\textbf{\i}} \rVert_{s+\mu_0} + \rVert \mathfrak{I}_\delta \rVert_{s+\mu_0}\rVert \hat{\textbf{\i}} \rVert_{s_0+\mu_0}\right).
