Furthermore, it holds that $M_x(q)=0$.

From Lemma~\ref{WB_expansion11},  \eqref{u_def1}, \eqref{actionssx} and \eqref{iso_tropic} , we have that
\[
u = \Phi^{WB}(\varepsilon v_\varepsilon(\theta_0,y_\delta) + \varepsilon^bz_0) = \varepsilon v_\varepsilon + \varepsilon^b z_0 + 6\varepsilon^{1+b}\partial_x\Pi_SK_1( v_\varepsilon,z_0) + 3\varepsilon^2\partial_x\Pi_{S^\perp}K_2(v_\varepsilon,v_\varepsilon) + \Phi^{WB}_{\ge 3}(U_\zeta(i_\delta)).
\]
Let $q=q(\varphi,x)$ be
\begin{align}\label{qes2rlaqkq}
q :=\varepsilon\left(v_\varepsilon - \bar{v} \right) + 3\varepsilon^2\partial_x\Pi_{S^\perp}\left( K_2(v_\varepsilon,v_\varepsilon) -K_2(\bar{v},\bar{v}) \right) + \varepsilon^bz_0 + 6\varepsilon^{1+b}\partial_x\Pi_SK_1( v_\varepsilon,z_0) + \Phi^{WB}_{\ge3}(U_\zeta(i_\delta)).
\end{align}
Clearly, we have the expression in \eqref{norm_phi_expansion2}. Noticing that $|v_\varepsilon(\theta_0,y_\delta)-\bar{v}| = O(\mathfrak{I}_\delta)$, more precisely (using \eqref{actionssx}),
\begin{equation}\label{vvvbbb}
\begin{aligned}
 \rVert v_\varepsilon - \bar{v}\rVert^{\text{Lip}(\gamma,\Omega_1)}_{s}&\le_{\mathtt{pe},s} \rVert \mathfrak{I}_\delta\rVert^{\text{Lip}(\gamma,\Omega_1)}_s,\\
  \rVert d_i(v_\varepsilon - \bar{v})(i_0)[\hat{\textbf{\i}}]\rVert_{s}^{\text{Lip}(\gamma,\Omega_1)}&\le_{\mathtt{pe},s} \rVert\hat{\textbf{\i}}\rVert_{s}^{\text{Lip}(\gamma,\Omega_1)}+\rVert\mathfrak{I}_\delta\rVert_{s}^{\text{Lip}(\gamma,\Omega_1)}\rVert\hat{\textbf{\i}}\rVert_{s_0}^{\text{Lip}(\gamma,\Omega_1)},
\end{aligned}
\end{equation} and  using \eqref{size_assumption_3}, the estimate \eqref{jjsdsd2sdsz} follows straightforwardly (for example, in the estimate for $q$ in \eqref{jjsdsd2sdsz}, $\varepsilon^3$ comes from $\Phi^{WB}_{\ge3}(U_\zeta(i_\delta))$ in \eqref{qes2rlaqkq} and $\varepsilon\rVert \mathfrak{I}_{\delta}\rVert^{\text{Lip}(\gamma,\Omega_1)}_{s+\mu_0}$ comes from $\varepsilon\left(v_\varepsilon - \bar{v} \right)$. All the other terms in \eqref{qes2rlaqkq} have smaller contribution in the estimates). Since $\Phi^{WB}(f)\in L^2_0$, for $f\in L^2_0$, we have that $M_x(u)=0$. Thus \eqref{norm_phi_expansion2} implies  $M_x(q)=0$, since $\overline{v}$ and $\partial_x\Pi_{S^\perp}K_2(\bar{v},\bar{v})$ have zero average.

