|L_2(j_1,k) - L_2(j_2,k)|&\overset{\eqref{m1sess234}}{\le_\alpha} |j_1-j_2|(|j_1| + |j_2|)^{\alpha-2}. \label{l1eess111s4}
\end{align}
Since $\mathtt{B}^N_{21}(j,k) = L_1(j,k) - L_1(j,-k)$, we expand
\begin{align}\label{rksdsdssxxxb21}
\mathtt{B}^N_{21}(j,k)&= (j+k)(L_2(j,k)+m_{1,\alpha}(j + k))^2 -  (j - k)(L_2(j,k)+m_{1,\alpha}(j - k))^2\nonumber\\
& = j((L_2(j,k)+m_{1,\alpha}(j+k))^2 - (L_2(j,k)+m_{1,\alpha}(j-k))^2) \nonumber\\
& \ +k ((L_2(j,k)+m_{1,\alpha}(j+k))^2 + (L_2(j,k)+m_{1,\alpha}(j-k))^2)\nonumber\\
& = j\underbrace{(2 L_2(j,k) + m_{1,\alpha}(j+k)+m_{1,\alpha}(j-k))}_{=:L_3(j,k)}\underbrace{(m_{1,\alpha}(j+k) - m_{1,\alpha}(j-k))}_{=:L_4(j,k)}\nonumber\\
& \ +2kL_2(j,k)^2 + \underbrace{2kL_2(j,k)(m_{1,\alpha}(j+k) +m_{1,\alpha}(j-k))}_{L_5(j,k)} + \underbrace{k(m_{1,\alpha}(j+k)^2+m_{1,\alpha}(j-k)^2)}_{=:L_6(j,k)}.
\end{align}
We have that
\begin{align}
|L_3(j,k)|&\overset{\eqref{l1eess111s2}}{\le_\alpha} |j|^{\alpha-1} + |k|^{\alpha-1},\label{qkfrjfmadl1}\\
|L_3(j_1,k) - L_3(j_2,k)|&\overset{\eqref{l1eess111s4},\eqref{m1sess234}}{\le_\alpha} |j_1-j_2|(|j_1| + |j_2|)^{\alpha-2} ,\label{qkfrjfmadl2}\\
|L_4(j,k)|&\overset{\eqref{m1sess1}}{\le_\alpha}|k| |j|^{\alpha-2},\label{qkfrjfmadl3}\\
|L_4(j_1,k) - L_4(j_2,k)|&\overset{\eqref{m1sess2}}{\le_\alpha}|j_1-j_2| (|j_1| + |j_2|)^{\alpha-3}|k|\label{qkfrjfmadl4}\\
|L_5(j,k)|&\overset{\eqref{l1eess111s2}}{\le_\alpha}|k|( |j|^{2\alpha-2} + |k|^{2\alpha-2}),\label{qkfrjfmadl5}\\
|L_5(j_1,k) - L_5(j_2,k)|&\overset{\eqref{l1eess111s4}\eqref{m1sess234}}{\le_\alpha}|k|  |j_1-j_2|(|j_1| + |j_2|)^{\alpha-2}(|j_1|^{\alpha-1} + |k|^{\alpha-1}),\label{qkfrjfmadl6}\\
|L_6(j,k)|&\le_\alpha |k| (|j|^{2\alpha-2} + |k|^{2\alpha-2}),\label{qkfrjfmadl7}\\
|L_6(j_1,k) - L_6(j_2,k)|&\overset{\eqref{m1sess234}}{\le_\alpha}|k|(|j_1|^{\alpha-1}+|j_2|^{\alpha-1}+|k|^{\alpha-1}) |j_1-j_2|(|j_1| + |j_2|)^{\alpha-2}.\label{qkfrjfmadl8}
\end{align}
Therefore,
\begin{align*}
|\mathtt{B}^N_{21}(j,k)|&\overset{\eqref{rksdsdssxxxb21}}=|j||L_3(j,k)||L_4(j,k)|+2k|L_2(j,k)|^2 + |L_5(j,k)|+|L_6(j,k)|\\
&\overset{\eqref{qkfrjfmadl1},\eqref{qkfrjfmadl4},\eqref{qkfrjfmadl5},\eqref{qkfrjfmadl7},\eqref{l1eess111s2}}{\le_\alpha}|k|(|j|^{2\alpha-2} + |k|^{\alpha-1}|j|^{\alpha-1} + |k|^{2\alpha-2})\\
