0, & \text{ if $i=k$,}\\
f\left(\frac{\mathtt{j}_i}{\mathtt{j}_k},\frac{\mathtt{j}_k}{\mathtt{j}_i}\right), & \text{ if $i\ne k$.}
\end{cases}
\end{align}
Note that for $0\ne x\in\mathbb{R}$, recalling $f$ from \eqref{fesjsdxc}, we see that
\[
f(x,x^{-1})= |x+x^{-1}|^{1+\alpha} + |x-x^{-1}|^{1+\alpha} - 2(x^{1+\alpha}+x^{-(1+\alpha)})
\]
satisfies
\begin{align}
|f(x,x^{-1})|\le_\alpha
\begin{cases}
|x|^{\alpha-3}, & \text{ if $|x|>1$},\\
|x|^{3-\alpha}, & \text{ if $|x|<1$.}
\end{cases}
\end{align}
